CREATE TABLE IF NOT EXISTS users (username VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY, password VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS documentaries (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, genre VARCHAR(60) NOT NULL, description VARCHAR(2000) NOT NULL, media VARCHAR(300) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS watchlist (username VARCHAR(80) COLLATE utf8mb4_bin NOT NULL, documentary_id BIGINT NOT NULL, PRIMARY KEY(username, documentary_id), FOREIGN KEY(username) REFERENCES users(username), FOREIGN KEY(documentary_id) REFERENCES documentaries(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
